int atl2_probe(struct pci_dev *pdev, const struct pci_device_id *ent)
{
    int err;
    struct net_device *ndev;
    struct atl2_adapter *adapter;
    void __iomem *reg;

    err = pci_enable_device(pdev);
    if (err)
        return err;

    err = pci_set_dma_mask(pdev, DMA_BIT_MASK(32));
    if (err)
        goto err_dma_mask;

    err = pci_request_regions(pdev, "atl2");
    if (err)
        goto err_pci_regions;

    reg = pci_iomap(pdev, 0, 0);
    if (!reg) {
        dev_err(&pdev->dev, "Failed to iomap BAR 0.\n");
        err = -ENOMEM;
        goto err_iomap;
    }

    ndev = alloc_etherdev(sizeof(struct atl2_adapter));
    if (!ndev) {
        err = -ENOMEM;
        goto err_alloc_dev;
    }

    SET_NETDEV_DEV(ndev, &pdev->dev);
    adapter = netdev_priv(ndev);
    adapter->pdev = pdev;
    adapter->reg = reg;
    adapter->ndev = ndev;

    ndev->irq = pdev->irq;
    ndev->netdev_ops = &atl2_netdev_ops;
    ndev->watchdog_timeo = 5 * HZ;

    err = register_netdev(ndev);
    if (err)
        goto err_register_netdev;

    setup_timer(&adapter->tx_timer, atl2_tx_timeout, (unsigned long)adapter);
    setup_timer(&adapter->phy_config_timer, atl2_phy_config, (unsigned long)adapter);

    err = atl2_read_mac_address(pdev, ndev);
    if (err) {
        dev_err(&pdev->dev, "Failed to read MAC address.\n");
        goto err_read_mac;
    }

    return 0;

err_read_mac:
    del_timer_sync(&adapter->tx_timer);
    del_timer_sync(&adapter->phy_config_timer);
err_register_netdev:
    free_netdev(ndev);
err_alloc_dev:
    pci_iounmap(pdev, reg);
err_iomap:
    pci_release_regions(pdev);
err_pci_regions:
    pci_clear_dma_mask(pdev);
err_dma_mask:
    pci_disable_device(pdev);
    return err;
}

