int atl2_probe(struct pci_dev *pdev, const struct pci_device_id *ent) {
    int err;
    struct net_device *netdev;
    struct atl2_adapter *adapter;

    err = pci_enable_device(pdev);
    if (err < 0)
        return err;

    if (pci_set_dma_mask(pdev, DMA_BIT_MASK(32)) < 0) {
        err = pci_set_dma_mask(pdev, DMA_BIT_MASK(32));
        if (err < 0)
            goto err_dma;
    }

    err = pci_request_regions(pdev, "atl2");
    if (err < 0)
        goto err_dma;

    netdev = alloc_etherdev(sizeof(struct atl2_adapter));
    if (!netdev) {
        err = -ENOMEM;
        goto err_out;
    }

    adapter = netdev_priv(netdev);
    adapter->pdev = pdev;
    adapter->netdev = netdev;
    SET_NETDEV_DEV(netdev, &pdev->dev);
    pci_set_drvdata(pdev, netdev);

    netdev->netdev_ops = &atl2_netdev_ops;
    netdev->watchdog_timeo = 5 * HZ;
    init_timer(&adapter->watchdog_timer);
    adapter->watchdog_timer.function = atl2_watchdog;
    adapter->watchdog_timer.data = (unsigned long)adapter;

    init_timer(&adapter->phy_config_timer);
    adapter->phy_config_timer.function = atl2_phy_config;
    adapter->phy_config_timer.data = (unsigned long)adapter;

    if (atl2_read_mac_addr(netdev)) {
        err = -EIO;
        goto err_out;
    }

    if (atl2_init_hw(adapter)) {
        err = -EIO;
        goto err_out;
    }

    err = register_netdev(netdev);
    if (err < 0)
        goto err_out;

    return 0;

err_out:
    pci_release_regions(pdev);
err_dma:
    pci_disable_device(pdev);
    return err;
}

int atl2_probe(struct pci_dev *pdev, const struct pci_device_id *ent) {
    int err;
    struct net_device *ndev;
    struct atl2_adapter *adapter;

    err = pcim_enable_device(pdev);
    if (err) {
        dev_err(&pdev->dev, "Failed to enable PCI device\n");
        return err;
    }

    err = pci_request_regions(pdev, "atl2");
    if (err) {
        dev_err(&pdev->dev, "Failed to request PCI regions\n");
        return err;
    }

    ndev = alloc_etherdev(sizeof(struct atl2_adapter));
    if (!ndev) {
        dev_err(&pdev->dev, "Failed to allocate network device\n");
        pci_release_regions(pdev);
        return -ENOMEM;
    }

    ndev->irq = pdev->irq;
    ndev->mem_start = pci_resource_start(pdev, 0);
    ndev->mem_end = pci_resource_end(pdev, 0);
    SET_NETDEV_DEV(ndev, &pdev->dev);

    adapter = netdev_priv(ndev);
    adapter->pdev = pdev;
    adapter->ndev = ndev;

    pci_set_drvdata(pdev, ndev);

    err = atl2_setup_dma_masks(pdev);
    if (err) {
        dev_err(&pdev->dev, "Failed to setup DMA masks\n");
        goto err_setup_dma;
    }

    err = atl2_read_mac_addr(pdev, ndev);
    if (err) {
        dev_err(&pdev->dev, "Failed to read MAC address\n");
        goto err_read_mac;
    }

    err = atl2_init_hw(adapter);
    if (err) {
        dev_err(&pdev->dev, "Failed to initialize hardware\n");
        goto err_init_hw;
    }

    timer_setup(&adapter->watchdog_timer, atl2_watchdog_timer, 0);
    timer_setup(&adapter->phy_config_timer, atl2_phy_config_timer, 0);

    ndev->netdev_ops = &atl2_netdev_ops;

    register_netdev(ndev);

    return 0;

err_init_hw:
err_read_mac:
err_setup_dma:
    free_netdev(ndev);
    pci_release_regions(pdev);
    return err;
}
